// RequestSessionsMount (#one-request-one-debug-session) — one debug session per request, bound to it.
//
// Each cycle: CLAIM every open request (atomically, one `bsc request claim` per request), then hold one
// session per claimed request, named for it (`debug-studio:req-<id>`), and close each when ITS request
// resolves. There is no pool, no cap, no pacing and no reaper — see `poolPlan.ts` for what each of those
// was for and why 1:1 removes the need.
//
// WHY THE MOUNT CLAIMS, rather than the session. `bsc request claim` takes the OLDEST open request; it
// cannot be pointed at a specific id. So the only way to bind a session to a KNOWN request is to claim
// first and spawn for whatever came back. That the claim is atomic is what makes this safe beside the
// standing debug session, which self-serves the same queue: whoever claims first holds it, and the other
// simply never sees it as open. No charter change was needed there, and none was made.
//
// It obeys a plan and decides nothing: `planRequestSessions` owns the gate and the reconcile. This mount
// is mechanics — claim, apply the plan (seed each session's charter, close finished ones, publish the
// live ids for the Glance graph).
//
// ── WHAT MAKES THIS SAFE TO SHIP ────────────────────────────────────────────────────────────────────
//  * UNCONDITIONAL (#debug-nodes-hang-off-the-session-that-filed-them) — the `autoSpawnDebugSessions`
//    toggle is gone. It defaulted OFF, which shipped this whole 1:1 machinery switched off: a request
//    was filed and then waited for someone to notice. The one remaining gate is not a preference —
//    `debug_repo_root` must resolve, because a shipped binary with no source tree cannot run these.
//  * EVERY session is a VISIBLE NODE in the Glance graph, labelled with its request and edged to the
//    session that filed it. That is what makes an app-started session supervisable: the user can see
//    it, open it, and stop it. It is the reason the ids are published below.
//  * The only role it can start is the plan's — `debugger` — and every pane is under the
//    `debug-studio:` prefix, so it is full-capability + role-less (#3520).
//  * Sessions launch FRESH (`claude`, never `--continue`) with `paneContinue: false` (#3497): each is
//    bound to one request and must never inherit another conversation.
//  * NOT bounded by a cap any more — a deliberate trade, recorded in `poolPlan.ts`. Concurrency is the
//    number of unresolved claimed requests.
import { useEffect, useRef, useState } from "react";
import { useAppStore } from "@/store";
import { bscJson, bscRun } from "@/shared/lib/core/bsc";
import { fireInvoke, safeInvoke } from "@/shared/lib/core/safeInvoke";
import { usePoll } from "@/shared/hooks/usePoll";
import { Box } from "@/shared/ui/layout/Box";
import { TerminalSlot } from "@/app/console/terminal/TerminalSlot";
import { planRequestSessions, type RequestSession, type RequestRow } from "@/shared/lib/session/poolPlan";
import { requestPaneId, requestIdFromPaneId } from "@/shared/lib/session/requestSpawn";
import { requestCharter, DEBUG_INIT_CMD } from "@/features/debug/requestSession";

/** How often to reconcile against the queue. Slow on purpose: a request is not urgent, and a session
 *  that is already working one is not waiting on this loop. */
const POLL_MS = 20_000;

/** One pane's runtime state, as `pty_pane_runtime` answers (Rust `PaneRuntime`, camelCase on the wire).
 *  Only `live` is read here — "is there a PTY session for this pane" — which is exactly the question
 *  `pty_create` would answer with RECONNECT rather than launch. */
interface PaneRuntime {
  paneId: string;
  live: boolean;
}

/** A raw row from `bsc request list --json` (snake_case from the Rust store). */
interface RawRequest {
  id: number;
  status: string;
  claimed_by?: string | null;
  /** WHO filed it (#debug-request-carries-its-origin) — the MERGED field, holding either a pane id or
   *  a free-text actor. Carried through to the charter so the spawned session knows whose workflow it
   *  is unblocking. Prefer `origin_pane` for anything that needs a SESSION. */
  origin?: string | null;
  /** The filing session's pane id specifically (`a-request-records-where-it-actually-came-from`) — the
   *  only value known to name a node, so it is what the Glance edge is drawn from. */
  origin_pane?: string | null;
  /** WHAT KIND the store classified the origin as — `pane` · `actor` · `both` · `unknown` · `absent`.
   *  Passed to the graph so the reader never re-derives it from the string's shape, which is how a
   *  shell filing by `lane-c4` used to be mistaken for a session belonging to another drill. */
  origin_kind?: string | null;
  /** Always populated by the store (explicit `--title`, else derived from the text). */
  display_title?: string | null;
  /** The branch a `land` named, for the app to merge. Present only while `landed`. */
  landed_branch?: string | null;
}

/** What `land_request_branch` answers (Rust `LandOutcome`, camelCase on the wire). */
interface LandOutcome {
  merged: boolean;
  detail: string;
  cleanedUp: boolean;
}

/**
 * Holds one session per open request. Renders nothing visible; each session's terminal is shown by
 * opening its node in the Glance graph.
 */
export function RequestSessionsMount() {
  // undefined = still resolving; null = no source tree (shipped binary — never launch into a missing
  // cwd); string = the repo root these sessions work in.
  const [repoRoot, setRepoRoot] = useState<string | null | undefined>(undefined);
  // The request sessions this mount tracks. Kept in a ref too so the poll reconciles against the latest
  // set without re-subscribing the interval (the ref is synced in an effect, never during render).
  const [sessions, setSessions] = useState<RequestSession[]>([]);
  const sessionsRef = useRef<RequestSession[]>([]);
  useEffect(() => { sessionsRef.current = sessions; }, [sessions]);
  // The last queue read, kept so the published node specs carry each request's origin + title.
  const [rows, setRows] = useState<RawRequest[]>([]);

  useEffect(() => {
    let alive = true;
    void safeInvoke<string | null>("debug_repo_root", undefined, null, () => {}).then((root) => {
      if (alive) setRepoRoot(root);
    });
    return () => { alive = false; };
  }, []);

  // #3522: review the queue ONCE per app start and drop completed (resolved) requests, so a long-dead
  // row cannot linger as a node. Keyed to mount rather than to a toggle transition (there is no toggle
  // any more) and never to the poll; `bscRun` is fire-and-forget (a missing binary is a no-op).
  useEffect(() => { void bscRun(null, ["request", "prune"]); }, []);

  // The reconcile loop, once per poll. `bscJson`/`bscRun` swallow a missing binary or verb and return the
  // fallback, so a machine without a working `bsc` simply never spawns rather than erroring in a loop.
  usePoll(
    // `isCancelled` is read by the LANDING pass below: it merges, rebuilds and injects across several
    // awaits, and a workspace change mid-flight must not go on driving a torn-down mount.
    async (isCancelled) => {
      if (!repoRoot) return;

      // 1 — CLAIM every open request, one atomic claim each, so that by the time the plan runs each has
      // a definite id to be bound to. Bounded by the open count read first, so a request the claim loop
      // itself creates could never spin it.
      //
      // NO `--by`. It stamps the holder at claim time, and the holder here is a pane named FOR the
      // request the claim is about to return — the id is not known until after. Nothing needs the stamp:
      // the binding is the pane name (`requestIdFromPaneId`), which is derived rather than recorded and
      // so cannot go stale. A `null` claim means the queue drained under us (the standing debug session
      // took the last one), which is exactly the race the atomic claim exists to make safe.
      // THE OFF SWITCH (`auto-spawn-has-no-off-switch`), read BEFORE the claim loop and not after it.
      //
      // Order is the whole correctness of this. Claiming is the side effect that turns `open` into
      // `claimed`, and `claimed` is what gets a session — so reading the flag after claiming would
      // leave the queue permanently altered by a cycle that then started nothing. That is a "pause"
      // which still takes work off the open queue, which is worse than not pausing. A paused cycle
      // therefore claims NOTHING and plans with `enabled: false`, which also closes the sessions
      // already running.
      //
      // Degrades to NOT paused, matching the store: a pause has to have been asked for to be true, and
      // a failed read must never silently stop the debug fleet.
      // ONE READ ANSWERS BOTH SWITCHES. `bsc request sessions --json` resolves the precedence — a
      // global policy outranks a transient pause — and hands back `allowed`, so this side combines
      // nothing and cannot drift from the rule. Two booleans combined by every caller is how the two
      // levels of the model precedence chain drifted apart earlier today.
      //
      // Degrades to ALLOWED, matching both stores: a failed read must never silently stop the debug
      // fleet, and neither switch is true unless someone set it.
      const gate = await bscJson<{ allowed: boolean }>(
        null,
        ["request", "sessions", "--json"],
        { allowed: true },
      );
      const paused = !gate.allowed;

      const open = paused
        ? []
        : (await bscJson<RawRequest[]>(null, ["request", "list", "--json"], [])).filter(
            (r) => r.status === "open",
          );
      for (let i = 0; i < open.length; i += 1) {
        const claimed = await bscJson<RawRequest | null>(null, ["request", "claim", "--json"], null);
        if (!claimed) break;
      }

      // 2 — PLAN + APPLY against the post-claim queue.
      const raw = await bscJson<RawRequest[]>(null, ["request", "list", "--json"], []);
      const requests: RequestRow[] = raw.map((r) => ({ id: r.id, status: r.status, claimedBy: r.claimed_by ?? null }));

      // THE LIVE SET IS DERIVED, NEVER REMEMBERED (#a-resolved-requests-debug-session-is-never-closed).
      //
      // `sessionsRef` is React state seeded `[]`, so it is empty after every remount — and `close` is
      // computed only from what it is handed. That made closing IMPOSSIBLE across a workspace change or
      // an app restart: the plan saw no sessions, closed nothing, and each orphan kept a `claude`
      // process running for good. It also silently disabled the `reload_sidecars` below, which fires on
      // close and is what makes a debugger's `bsc` fix live without a manual restart.
      //
      // The binding was never in doubt — the pane NAME encodes the request id — so the live set can be
      // rebuilt from the queue every poll and cannot go stale. `sessionsRef` is still unioned in as a
      // CANDIDATE, because a request removed from the list outright (`bsc request remove`, or the prune
      // above) yields no pane name to ask about, and the remembered set is the only thing that can still
      // name that one. It is a candidate, not an answer: everything here is filtered by real liveness.
      const candidates = [
        ...new Set([...raw.map((r) => requestPaneId(r.id)), ...sessionsRef.current.map((s) => s.paneId)]),
      ];
      const runtime = await safeInvoke<PaneRuntime[]>("pty_pane_runtime", { paneIds: candidates }, []);
      const live: RequestSession[] = runtime.filter((p) => p.live).map((p) => ({ paneId: p.paneId }));

      // 2a — LAND anything the debug session says is ready (#a-debug-session-strands-its-work).
      //
      // The session cannot merge its own branch: git refuses to check out `develop` in a second
      // worktree, and a debug session lives in one. So it names the branch and this does the merge,
      // the teardown, and the hand-off to the session that FILED the request — the only one that can
      // say whether its own workflow is unblocked.
      //
      // Sequential, not `Promise.all`: every landing merges into the same branch in the same tree, so
      // two at once would race on the index and the second would refuse on a dirty tree it caused.
      for (const r of raw.filter((x) => x.status === "landed")) {
        const outcome = await safeInvoke<LandOutcome | null>(
          "land_request_branch",
          { branch: r.landed_branch ?? "" },
          null,
        );
        if (isCancelled() || !outcome) continue;
        // The outcome goes on the THREAD either way — a refusal the debug session cannot read is a
        // request that silently stops moving, which is the failure this whole loop exists to remove.
        await bscRun(null, ["request", "note", String(r.id), outcome.detail, "--from", "app"]);
        if (!outcome.merged) {
          // Back to its own session, branch cleared. Not `resolved` (the fix is incomplete) and not
          // left `landed` (it would retry the same refusal every poll).
          await bscRun(null, ["request", "unland", String(r.id)]);
          continue;
        }
        // The merge is in develop; make it LIVE before asking anyone to test it, or the filer verifies
        // the old binary and reports a failure the fix already addressed.
        await safeInvoke<[string, string | null][]>("reload_sidecars", undefined, [], () => {});
        // The ask goes on the THREAD, not into the filer's stdin.
        //
        // Injecting it would be an app-initiated `injectPrompt`, and `injectCallers.test.ts` keeps that
        // set deliberately EMPTY (#app-stops-pushing-prompts): "injectPrompt now has NO callers at all,
        // which is a stronger boundary than a one-entry allow-list — there is nothing to argue onto."
        // `injectRedirect` survives only as a USER click. An app poll pushing a prompt into a session
        // is exactly what that boundary removed, so this records the ask durably instead and leaves
        // WAKING the filer to be decided rather than assumed.
        const filer = r.origin?.trim();
        await bscRun(null, [
          "request",
          "note",
          String(r.id),
          `@${filer ?? "filer"} — the fix you filed has landed: ${outcome.detail}. ` +
            `Re-run the command that failed, then report: ` +
            `\`bsc request verify ${r.id} --ok --note "<what you saw>"\` if the gap is gone, or ` +
            `\`bsc request verify ${r.id} --fail --note "<what still fails>"\` to hand it back. ` +
            `You are the only session that can tell — it was your workflow that hit this.`,
          "--from",
          "app",
        ]);
        // Only now is it awaiting a verdict. Flipping before the ask would leave a request waiting on
        // a verification nobody was asked for.
        await bscRun(null, ["request", "verifying", String(r.id)]);
      }
      if (isCancelled()) return;

      const plan = planRequestSessions({ requests, sessions: live, enabled: !paused });

      // STOP IT, don't just stop RENDERING it. Dropping a pane from `sessions` unmounts its
      // `TerminalSlot`, and `TerminalView`'s cleanup deliberately leaves the backend PTY alive so a
      // console tab-switch reconnects rather than respawns (`useStudioReaper` documents the same trap and
      // issues the same explicit kill). So the unmount only ever reclaimed the xterm: the `claude`
      // process under a finished request went on running with nothing on screen to show for it.
      for (const paneId of plan.close) fireInvoke("pty_kill", { paneId }, console.error);

      // Free the store fields of every closed pane, so a stopped session leaves nothing behind.
      if (plan.close.length) {
        useAppStore.setState((st) => {
          const prompts = { ...st.paneStartupPromptText };
          const cont = { ...st.paneContinue };
          for (const paneId of plan.close) { delete prompts[paneId]; delete cont[paneId]; }
          return { paneStartupPromptText: prompts, paneContinue: cont };
        });
      }

      // A CLOSE means a request just resolved, and a resolved `bsc` request means the session very
      // likely rebuilt the binary. Re-stage it and retire the warm child so the fix is LIVE for the next
      // `bsc` call — the last mile of "a designer's request gets processed live", which without this
      // ends in a manual app restart no matter how fast the fix was.
      //
      // Fire-and-forget: a failed reload must not stop the mount reconciling. It is also safe to call
      // when nothing was rebuilt (staging is an idempotent copy) and in a release bundle (a no-op), so
      // it does not need to know WHY the session closed.
      if (plan.close.length) {
        void safeInvoke<[string, string | null][]>("reload_sidecars", undefined, [], () => {});
      }

      if (plan.start.length) {
        // The rows by id, so the charter can name the request and the session that filed it
        // (#debug-request-carries-its-origin). Read from `raw` — the post-claim list — because that is
        // the read that already happened; a session started without its origin would be told nothing
        // about whose workflow it is unblocking, and the relationship would exist only in the graph.
        const byId = new Map(raw.map((r) => [r.id, r]));
        // Seed the launch fields TerminalView reads: the charter naming THIS request (baked as
        // --initial-message) and paneContinue=false (#3497 — never resume; each session is bound to one
        // request and must not inherit another conversation).
        useAppStore.setState((st) => {
          const prompts = { ...st.paneStartupPromptText };
          const cont = { ...st.paneContinue };
          for (const id of plan.start) {
            const row = byId.get(id);
            prompts[requestPaneId(id)] = requestCharter({
              id,
              origin: row?.origin ?? null,
              display_title: row?.display_title ?? null,
            });
            cont[requestPaneId(id)] = false;
          }
          return { paneStartupPromptText: prompts, paneContinue: cont };
        });
      }
      setSessions([...plan.sessions, ...plan.start.map((id) => ({ paneId: requestPaneId(id) }))]);
      // Publish the ROWS, not just the ids (#debug-nodes-hang-off-the-session-that-filed-them): the
      // graph needs each request's origin and title to label its node and edge it to the session that
      // filed it, and this poll is the only place that already holds them.
      setRows(raw);
    },
    POLL_MS,
    [repoRoot],
  );

  // Publish the live REQUESTS so the Glance graph can render a node per request. Without this the
  // sessions run with no node — unopenable, unsupervisable, unstoppable.
  //
  // The published value carries the ORIGIN and TITLE alongside the id
  // (#debug-nodes-hang-off-the-session-that-filed-them), because the node is labelled `debug - <title>`
  // and edged to the session that filed it. A bare id could do neither, which is why every request node
  // used to be called `debugger-req-<n>` and drawn to the designer regardless of who actually filed it.
  const setActiveDebugRequests = useAppStore((s) => s.setActiveDebugRequests);
  useEffect(() => {
    const live = new Map(rows.map((r) => [r.id, r]));
    setActiveDebugRequests(
      sessions
        .map((s) => requestIdFromPaneId(s.paneId))
        .filter((n): n is number => n != null)
        .map((id) => ({
          id,
          origin: live.get(id)?.origin ?? null,
          // The store's own classification travels with the row
          // (`a-request-records-where-it-actually-came-from`), so the graph edges to a real session and
          // draws an actor-filed request unparented instead of omitting it from every graph.
          originPane: live.get(id)?.origin_pane ?? null,
          originKind: live.get(id)?.origin_kind ?? null,
          title: live.get(id)?.display_title ?? null,
        })),
    );
  }, [sessions, rows, setActiveDebugRequests]);

  // The charter for a pane, built from the rows this poll already read, so it travels as a PROP beside
  // `initCmd` (`a-debug-session-launches-with-no-charter`). The store write above stays — it is what a
  // pane seeded by any other route reads — but the prop is what makes the launch correct regardless of
  // when that write lands, because a prop cannot be missed by a one-shot read.
  const charterFor = (paneId: string): string | undefined => {
    const id = requestIdFromPaneId(paneId);
    if (id == null) return undefined;
    const row = rows.find((r) => r.id === id);
    return requestCharter({ id, origin: row?.origin ?? null, display_title: row?.display_title ?? null });
  };

  if (!repoRoot || !sessions.length) return null;
  return (
    <Box
      aria-hidden
      style={{
        position: "absolute", left: -99999, top: 0, width: 800, height: 600,
        overflow: "hidden", pointerEvents: "none", display: "flex", flexDirection: "column",
      }}
    >
      {sessions.map((s) => (
        <TerminalSlot
          key={s.paneId}
          paneId={s.paneId}
          primary
          parked
          visible={false}
          initialCwd={repoRoot}
          initCmd={DEBUG_INIT_CMD}
          startupPrompt={charterFor(s.paneId)}
        />
      ))}
    </Box>
  );
}

